/** One active staff member as a picker shows them (GET /staff/lookup): the facts on their badge and the registration their stamp prints, nothing else. */
export interface StaffLookupOut {
  /** The id a form's staff field takes (contrast_doctor_id, employee_id, ...) */
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  department_name: string | null;
  /** The council they are registered with (PMDC: a doctor or dentist; PNC: a nurse); null: none */
  license_type: "PMDC" | "PNC" | "Other" | null;
  /** As their stamp prints it, e.g. "PMDC 12345-P"; null: no number on file */
  registration: string | null;
  /** Their login, the id a form's user field takes (an action's owner, a signer, the person told); null: no login (decision 62) */
  user_id: number | null;
}

/** Who is oriented — GET /api/v1/personnel/orientation (who may call: holders of personnel.view or personnel.manage). */
export function orientationStatus(query?: { department_id?: number | null; incomplete_only?: boolean }): Promise<OrientationStatusOut[]> {
  return api<OrientationStatusOut[]>("GET", withQuery(`/personnel/orientation`, query), undefined);
}

/** Orientation topics — GET /api/v1/personnel/orientation-topics (who may call: holders of personnel.view or personnel.manage). */
export function orientationTopics(query?: { active_only?: boolean }): Promise<OrientationTopicOut[]> {
  return api<OrientationTopicOut[]>("GET", withQuery(`/personnel/orientation-topics`, query), undefined);
}

/** Adapt an orientation topic — PUT /api/v1/personnel/orientation-topics/{code} (who may call: holders of personnel.manage). */
export function updateTopic(code: string, body: OrientationTopicIn): Promise<OrientationTopicOut> {
  return api<OrientationTopicOut>("PUT", `/personnel/orientation-topics/${code}`, body);
}

/** Record the topics covered with a member of staff — POST /api/v1/personnel/employees/{employee_id}/orientation (who may call: holders of personnel.manage). */
export function recordOrientation(employee_id: number, body: OrientationIn): Promise<OrientationStatusOut> {
  return api<OrientationStatusOut>("POST", `/personnel/employees/${employee_id}/orientation`, body, { idempotent: true });
}

